const TOOL_ID:&str="toolcall-firewall"; const TOOL_BIN:&str="toolcallfw"; const TOOL_DESC:&str="MCPツール呼び出しのポリシー検査と実行制御"; const TOOL_PROFILE:&str="tool-call";
use serde::{Deserialize,Serialize};
use sha2::{Digest,Sha256};
use std::{env,fs,io::{self,Read},path::{Path,PathBuf},process::Command,time::{Duration,SystemTime,UNIX_EPOCH}};
use walkdir::WalkDir;
#[derive(Serialize,Deserialize,Default,Clone)] struct State { files: std::collections::BTreeMap<String,String>, trusted: Vec<String>, events: Vec<String> }
fn state_path()->PathBuf { dirs::data_local_dir().unwrap_or_else(||PathBuf::from(".")).join("HiroyukiGPU").join(TOOL_ID) }
fn load()->State { fs::read(state_path().join("state.json")).ok().and_then(|b|serde_json::from_slice(&b).ok()).unwrap_or_default() }
fn save(s:&State)->io::Result<()> { let d=state_path(); fs::create_dir_all(&d)?; fs::write(d.join("state.json"),serde_json::to_vec_pretty(s).unwrap()) }
fn hash(p:&Path)->io::Result<String>{let mut f=fs::File::open(p)?;let mut h=Sha256::new();let mut b=[0;65536];loop{let n=f.read(&mut b)?;if n==0{break}h.update(&b[..n]);}Ok(format!("{:x}",h.finalize()))}
fn expand(s:&str)->PathBuf { if s=="~" { dirs::home_dir().unwrap_or_default() } else if let Some(x)=s.strip_prefix("~/"){dirs::home_dir().unwrap_or_default().join(x)}else{PathBuf::from(s)} }
fn help(){println!("{} {}\n{}\n\nUsage: {} <command> [path|id] [options]\nCommands: scan, watch, init, protect, verify, diff, quarantine, isolate, restore, status, logs, trust, revoke, audit, run, inspect, import, capture, report, stop, export, install, policy, allow, deny, approve, list, enforce, disable\nOptions: --json --verbose --quiet --dry-run --recursive -- --command",TOOL_BIN,env!("CARGO_PKG_VERSION"),TOOL_DESC,TOOL_BIN);}
fn walk(path:&Path, recursive:bool)->Vec<PathBuf>{if path.is_file(){return vec![path.to_path_buf()]} if !path.exists(){return vec![]} WalkDir::new(path).follow_links(false).max_depth(if recursive{32}else{1}).into_iter().filter_map(Result::ok).filter(|e|e.file_type().is_file()).map(|e|e.path().to_path_buf()).collect()}
fn suspicious(p:&Path)->Vec<String>{let n=p.file_name().unwrap_or_default().to_string_lossy().to_lowercase();let ext=p.extension().unwrap_or_default().to_string_lossy().to_lowercase();let mut f=vec![];let profile=TOOL_PROFILE;let names=match profile{"agent-instructions"=>vec!["agents.md","claude.md","gemini.md",".cursorrules","copilot-instructions.md"],"launch-agent"=>vec![".plist"],"python-startup"=>vec![".pth","sitecustomize.py","usercustomize.py"],"git-hook"=>vec!["pre-commit","post-commit","prepare-commit-msg","pre-push"],"shell-config"=>vec![".zshrc",".zprofile",".bashrc",".bash_profile"],"lockfile"=>vec!["cargo.lock","package-lock.json","pnpm-lock.yaml","yarn.lock","poetry.lock","uv.lock","pipfile.lock"],"workflow"=>vec![".yml",".yaml"],"docker-compose"=>vec![".yml",".yaml"],"npm-lifecycle"=>vec!["package.json"],"browser-extension"=>vec!["manifest.json"],"vscode-extension"=>vec!["package.json"],"mcp-config"=>vec![".json",".toml",".yaml",".yml"],_=>vec![]};if names.iter().any(|x|n==*x||ext==*x){f.push(format!("sensitive target for {}",TOOL_BIN));} if let Ok(meta)=fs::metadata(p){if meta.len()<=2_000_000 { if let Ok(t)=fs::read_to_string(p){let l=t.to_lowercase();for (pat,msg) in [("ignore all previous instructions","instruction override"),("reveal system prompt","prompt exfiltration"),("send the api key","secret exfiltration"),("curl ","remote fetch command"),("wget ","remote fetch command"),("base64 -d","encoded execution"),("chmod +x","executable permission change"),("process.env","environment access"),("child_process","process execution"),("privileged: true","privileged container"),("network_mode: host","host network")]{if l.contains(pat){f.push(msg.into())}}if profile=="docker-compose"&&(l.contains("/var/run/docker.sock")||l.contains("privileged: true")){f.push("high-risk container setting".into())}if profile=="npm-lifecycle"&&l.contains("\"scripts\""){f.push("package lifecycle scripts declared; inspect before install".into())} }} } f }
fn scan(path:&Path,json:bool,recursive:bool)->i32{let mut findings=vec![];let files=walk(path,recursive);for p in files{for why in suspicious(&p){findings.push(serde_json::json!({"path":p,"finding":why}));}}if json{println!("{}",serde_json::json!({"tool":TOOL_BIN,"target":path,"findings":findings,"count":findings.len()}));}else if findings.is_empty(){println!("{}: no findings in {}",TOOL_BIN,path.display());}else{for f in &findings{println!("{}: {}",f["path"],f["finding"])}println!("{} finding(s)",findings.len());} if findings.is_empty(){0}else{1}}
fn protect(path:&Path)->io::Result<()> {let mut s=load();let ps=walk(path,true);for p in ps{if let Ok(h)=hash(&p){s.files.insert(p.to_string_lossy().into_owned(),h);}}s.events.push(format!("baseline {} files",s.files.len()));save(&s)?;println!("Protected {} file(s)",s.files.len());Ok(())}
fn verify(json:bool)->i32{let s=load();let mut changes=vec![];for (p,h) in &s.files{match hash(Path::new(p)){Ok(now) if &now!=h=>changes.push(serde_json::json!({"path":p,"status":"modified","sha256":now})),Err(_)=>changes.push(serde_json::json!({"path":p,"status":"missing"})),_=>()}}if json{println!("{}",serde_json::json!({"changes":changes,"count":changes.len()}))}else{for c in &changes{println!("{}: {}",c["path"],c["status"])}if changes.is_empty(){println!("All {} protected files match baseline",s.files.len())}}if changes.is_empty(){0}else{1}}
fn quarantine(path:&Path,dry:bool)->io::Result<()> {if !path.exists(){return Err(io::Error::new(io::ErrorKind::NotFound,"target does not exist"))}let id=format!("{}-{}",SystemTime::now().duration_since(UNIX_EPOCH).unwrap().as_secs(),path.file_name().unwrap_or_default().to_string_lossy());let q=state_path().join("quarantine").join(&id);if dry{println!("Would move {} to {}",path.display(),q.display());return Ok(())}fs::create_dir_all(q.parent().unwrap())?;fs::rename(path,&q)?;let mut s=load();s.events.push(format!("quarantine\t{}\t{}",q.display(),path.display()));save(&s)?;println!("Quarantined as {}",id);Ok(())}
fn restore(id:&str)->io::Result<()> {let mut s=load();let rec=s.events.iter().rev().find(|x|x.starts_with("quarantine\t")&&x.contains(&format!("/{}\t",id)));let Some(r)=rec else{return Err(io::Error::new(io::ErrorKind::NotFound,"quarantine id not found"))};let a:Vec<_>=r.splitn(3,'\t').collect();let from=PathBuf::from(a[1]);let to=PathBuf::from(a[2]);if to.exists(){return Err(io::Error::new(io::ErrorKind::AlreadyExists,"restore destination exists"))}if let Some(p)=to.parent(){fs::create_dir_all(p)?}fs::rename(from,to)?;s.events.push(format!("restored {}",id));save(&s)?;println!("Restored {}",id);Ok(())}
pub fn run()->i32{let a:Vec<String>=env::args().skip(1).collect();if a.is_empty()||a.iter().any(|x|x=="--help"||x=="-h"){help();return 0}if a.iter().any(|x|x=="--version"||x=="-V"){println!("{} {}",TOOL_BIN,env!("CARGO_PKG_VERSION"));return 0}let cmd=&a[0];let json=a.iter().any(|x|x=="--json");let recursive=a.iter().any(|x|x=="--recursive");let dry=a.iter().any(|x|x=="--dry-run");let target=a.iter().skip(1).find(|x|!x.starts_with('-')&&*x!="--").map(|s|expand(s)).unwrap_or_else(||env::current_dir().unwrap_or_default());let result:io::Result<i32>=(||Ok(match cmd.as_str(){"scan"|"inspect"|"audit"=>scan(&target,json,recursive||target.is_dir()),"watch"=>{println!("Watching {} every 2s (Ctrl-C to stop)",target.display());let mut last=String::new();loop{let _=scan(&target,false,true);let now=format!("{:?}",SystemTime::now());if now==last{}last=now;std::thread::sleep(Duration::from_secs(2));}},"init"|"protect"=>{protect(&target)?;0},"verify"|"diff"=>verify(json),"quarantine"|"isolate"|"disable"=>{quarantine(&target,dry)?;0},"restore"=>{restore(a.get(1).map(String::as_str).unwrap_or(""))?;0},"status"=>{let s=load();println!("protected_files={} events={}",s.files.len(),s.events.len());0},"logs"=>{for x in load().events{println!("{}",x)}0},"trust"|"allow"|"approve"=>{let mut s=load();let x=a.get(1).cloned().unwrap_or_default();if !s.trusted.contains(&x){s.trusted.push(x.clone())}save(&s)?;println!("Trusted {}",x);0},"revoke"|"deny"=>{let mut s=load();let x=a.get(1).cloned().unwrap_or_default();s.trusted.retain(|t|t!=&x);save(&s)?;0},"list"=>{for x in load().trusted{println!("{}",x)}0},"run"=>{let i=a.iter().position(|x|x=="--").map(|i|i+1).unwrap_or(1);if i>=a.len(){return Err(io::Error::new(io::ErrorKind::InvalidInput,"run requires -- COMMAND"))}let mut c=Command::new(&a[i]);c.args(&a[i+1..]);if TOOL_PROFILE=="secrets"{c.env_clear();for k in ["PATH","HOME","USER","SHELL","TMPDIR","LANG","TERM"]{if let Some(v)=env::var_os(k){c.env(k,v);}}for k in load().trusted{if let Some(v)=env::var_os(&k){c.env(k,v);}}}let st=c.status()?;st.code().unwrap_or(4)},"capture"|"stop"|"report"|"export"=>{println!("{}: this command requires explicit platform support; no process was changed",cmd);4},_=>{eprintln!("Unknown command: {} (use --help)",cmd);2}}))();match result{Ok(n)=>n,Err(e)=>{eprintln!("{}",e);if e.kind()==io::ErrorKind::NotFound{2}else{4}}}}

#[cfg(test)] mod tests {
 use super::*;
 #[test] fn prompt_override_is_reported(){ let p=env::temp_dir().join(format!("{}-{}-prompt.md",TOOL_ID,std::process::id())); fs::write(&p,"ignore all previous instructions").unwrap(); let findings=suspicious(&p); let _=fs::remove_file(&p); assert!(findings.iter().any(|x|x=="instruction override")); }
 #[test] fn computes_sha256(){ let p=env::temp_dir().join(format!("{}-{}-hash",TOOL_ID,std::process::id())); fs::write(&p,"abc").unwrap(); let got=hash(&p).unwrap(); let _=fs::remove_file(&p); assert_eq!(got,"ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad"); }
}
